'use client'

import * as React from 'react'

// The component brings its own styles. Without this a `gamestage-ui add` installs a
// working but completely unstyled Feedback, and `tsc --noEmit` passes on it,
// so the gate cannot catch it.
import './feedback.css'
import { CrossGlyph, StarGlyph, TickGlyph } from './glyphs'

// The cue runtime. `./feel` is a local re-export shim in this repo and the
// installed sibling file in a host application, so the one specifier resolves
// in both places. With no provider above it, `useGameFeel` is a no-op.
import { useGameFeel } from './feel'

/**
 * Feedback: the response to the player's last act.
 *
 * One component, four variants, from specimen 5d. Correct is a word on a
 * positive plate with a tick, tilted three degrees and popping in. Wrong is
 * the same plate on the surface with a dashed negative ring and a cross,
 * shaking. Score is no plate at all: the bare `+100` in positive, floating up
 * beside the stat it changed. Reward is a surface card on the reward ring with
 * a star, an "Earned" kicker over the reward's name, slamming in and staying
 * until tapped.
 *
 * The element that moves is the plate itself, `data-gs-animates="motion"`,
 * and it stops dead under reduced motion. The glyph and the words inside it
 * are `data-gs-animates="emphasis"`, because a colour, glyph or text change is
 * how a player who cannot see movement still gets the answer.
 *
 * One feedback on screen at a time. The plate is keyed on what it says, so a
 * new variant or a new message replaces the old plate rather than stacking on
 * it, and replays its motion in doing so; the live region around it stays
 * put, so a screen reader hears the change.
 *
 * It performs nothing. It does not decide whether the last act was right, does
 * not know the running score, and does not settle a reward. The host has
 * already decided that by the time it hands this a variant, and this renders
 * it. Rendering is synchronous with the prop on purpose: REQ-045 puts a 100ms
 * ceiling on the gap between a tap and the first visible feedback, and nothing
 * here awaits anything between the prop landing and `[data-gs-feedback]`
 * landing in the DOM.
 */

export type FeedbackVariant = 'correct' | 'wrong' | 'score' | 'reward'

export interface FeedbackProps extends Omit<React.HTMLAttributes<HTMLDivElement>, 'children'> {
  /** Which of the four contract values this renders. */
  variant: FeedbackVariant
  /**
   * The word on the plate. Each variant has a default ("Correct", "Wrong", the
   * signed delta, "Reward"), so a bare `<Feedback variant="correct" />` is a
   * complete, accessible render; a reward passes its name here.
   */
  label?: string
  /**
   * The optional line under the word: the reason an answer was wrong, what a
   * reward is for. Read after the label by a screen reader.
   */
  message?: string
  /**
   * The kicker over a reward's name. "Earned" unless the host says otherwise.
   * Rendered on the reward variant only.
   */
  note?: string
  /**
   * The signed amount a value changed by, e.g. `50` or `-10`. On `score` it is
   * the whole message; on `correct` it follows the word ("Correct +100", as
   * specimen 5e draws it). Rides `data-gs-delta`, which the attribute contract
   * shares with any element reporting a value's change rather than holding the
   * value itself.
   */
  delta?: number
  /**
   * Called when the feedback has finished. Passing it turns the lifetime on:
   * correct and wrong hold for the drawing's 1200ms and fade over 200ms; score
   * fades once its float ends; reward stays until tapped and fades then. Leave
   * it out and the feedback stays as rendered, for a host that removes it
   * itself (a changing `key`, a `null` on the next round).
   */
  onDismiss?: () => void
}

/** Fallbacks for a host that renders a variant with no label of its own. */
const DEFAULT_LABEL: Record<FeedbackVariant, string> = {
  correct: 'Correct',
  wrong: 'Wrong',
  score: 'Score',
  reward: 'Reward',
}

/** Glyphs, because colour alone is not an answer. Score has none: the number
 *  itself, floating up, is the signal. */
const GLYPH: Partial<Record<FeedbackVariant, React.ReactNode>> = {
  correct: <TickGlyph />,
  wrong: <CrossGlyph />,
  reward: <StarGlyph filled />,
}

/**
 * One capability per outcome, from specimen 5d: a correct answer pops, a wrong
 * one shakes, a score floats up, a reward slams in. motion.css plays the
 * capability on the element that carries it, which is the plate; the glyph and
 * the label inside stay emphasis, the half that survives reduced motion.
 */
const MOTION: Record<FeedbackVariant, 'pop' | 'shake' | 'floatup' | 'slam'> = {
  correct: 'pop',
  wrong: 'shake',
  score: 'floatup',
  reward: 'slam',
}

/**
 * What each variant asks for, in the order the design lists it.
 *
 * Typed off the runtime's own signature rather than by importing its cue-name
 * union: after a registry install `./feel` is the provider file alone, and a
 * type imported from a file the installer does not ship is a component that
 * only compiles inside this repo.
 */
type CueRequest = Parameters<ReturnType<typeof useGameFeel>['cue']>

const CUES: Record<FeedbackVariant, ReadonlyArray<CueRequest>> = {
  correct: [
    ['correct', 'sfx'],
    ['success', 'haptic'],
  ],
  wrong: [
    ['wrong', 'sfx'],
    ['error', 'haptic'],
  ],
  score: [
    ['score', 'sfx'],
    ['light', 'haptic'],
  ],
  reward: [
    ['reward', 'sfx'],
    ['success', 'haptic'],
  ],
}
/** The name of the exit keyframe in feedback.css, matched on animationend. */
const EXIT = 'gs-feedback-exit'

function formatDelta(delta: number): string {
  if (delta > 0) return `+${delta}`
  if (delta < 0) return `−${Math.abs(delta)}`
  return `${delta}`
}

export function Feedback({
  variant,
  label,
  message,
  note,
  delta,
  onDismiss,
  className,
  onAnimationEnd,
  ...rest
}: FeedbackProps) {
  const word =
    label ??
    (variant === 'score' && delta !== undefined
      ? formatDelta(delta)
      : variant === 'correct' && delta !== undefined
        ? `${DEFAULT_LABEL.correct} ${formatDelta(delta)}`
        : DEFAULT_LABEL[variant])
  const kicker = variant === 'reward' ? (note ?? 'Earned') : undefined
  const glyph = GLYPH[variant]
  const motion = MOTION[variant]

  // The design's feedback sheet, specimens 4a to 4d, gives each variant its
  // sound and its haptic: "Correct · sfx.correct (bright, short) ·
  // haptic.success", "Wrong · sfx.wrong (low, dull, never harsh) ·
  // haptic.error", "Score +100 · sfx.score (ticks per 10 pts) · haptic.light",
  // and the reward specimen 3f's "sfx.reveal → sfx.reward · haptic.success".
  //
  // On mount, once, because a feedback is one settlement: the registry docs
  // already tell a host to mount it fresh per settlement with a changing `key`
  // rather than toggling one instance, which is the same thing the shake and
  // the float need. A `choice` that settles at the same moment asks for
  // sfx.correct too, and the runtime collapses the pair into one sound.
  const { cue } = useGameFeel()
  const fired = React.useRef(false)
  React.useEffect(() => {
    if (fired.current) return
    fired.current = true
    for (const request of CUES[variant]) cue(...request)
  }, [variant, cue])
  // The reward stays until tapped. Tapping it starts the exit fade; the fade's
  // end is what calls the host, so the host removes an element that has
  // already gone rather than one mid-fade.
  const [exiting, setExiting] = React.useState(false)
  const timed = onDismiss !== undefined && variant !== 'reward'
  const tappable = onDismiss !== undefined && variant === 'reward'

  const name = [kicker, word, message].filter(Boolean).join('. ')

  const content = (
    <>
      {glyph ? (
        <span className="gs-feedback__glyph" data-gs-scope="feedback" data-gs-part="glyph" data-gs-animates="emphasis" aria-hidden="true">
          {glyph}
        </span>
      ) : null}
      <span className="gs-feedback__text">
        {kicker ? (
          <span className="gs-feedback__note" data-gs-scope="feedback" data-gs-part="note" data-gs-animates="emphasis" aria-hidden="true">
            {kicker}
          </span>
        ) : null}
        {/* The score's number is a display number, so it carries the shared
            display class and the theme's shadow reaches it the way it reaches
            every other number a player reads. The words on a plate are the
            title face, set in feedback.css. */}
        <span
          className={['gs-feedback__label', variant === 'score' ? 'gs-display-type' : null].filter(Boolean).join(' ')}
          data-gs-scope="feedback"
          data-gs-part="label"
          data-gs-animates="emphasis"
          aria-hidden="true"
        >
          {word}
        </span>
        {message ? (
          <span className="gs-feedback__detail" data-gs-scope="feedback" data-gs-part="detail" data-gs-animates="emphasis" aria-hidden="true">
            {message}
          </span>
        ) : null}
      </span>
    </>
  )

  // The plate. Keyed on what it says, so a new outcome is a new element and
  // its motion plays again; the live region outside it does not remount, so
  // the change is announced. The part is `motion` because the job of this
  // element is to be the thing that moves, whatever it plays.
  const plateKey = `${variant}|${word}|${message ?? ''}`
  const plateProps = {
    className: 'gs-feedback__motion',
    'data-gs-scope': 'feedback',
    'data-gs-part': 'motion',
    'data-gs-motion': motion,
    'data-gs-animates': 'motion',
  } as const

  return (
    <div
      {...rest}
      className={['gs-feedback', timed ? 'gs-feedback--timed' : null, exiting ? 'gs-feedback--exit' : null, className]
        .filter(Boolean)
        .join(' ')}
      data-gs-component="feedback"
      data-gs-feedback={variant}
      data-gs-delta={delta}
      role="status"
      aria-label={name}
      onAnimationEnd={(event) => {
        onAnimationEnd?.(event)
        if (event.animationName === EXIT && event.target === event.currentTarget) onDismiss?.()
      }}
    >
      {tappable ? (
        // A reward that stays until tapped is a control, so it is a button and
        // is reachable from a keyboard. Its name is the feedback's own.
        <button key={plateKey} {...plateProps} type="button" aria-label={`${name}. Dismiss`} onClick={() => setExiting(true)}>
          {content}
        </button>
      ) : (
        <span key={plateKey} {...plateProps} aria-hidden="true">
          {content}
        </span>
      )}
    </div>
  )
}

/* Feedback. Every value comes from a token; nothing here is a literal colour.

   Specimen 5d draws the four variants, correct, wrong, score and reward, and
   design/twins/5d.json measures ours against them declaration by declaration;
   3i, the older game-feel sheet, still pairs the three frames it draws. Only
   the resting appearance is here: the keyframes a plate plays are the motion
   layer's (packages/tokens/motion.css) and the pairing does not measure them.

   The plate anatomy the drawing gives: glyph 28, label at 18/900 in the
   display face in capitals, gap 10, padding 12 18, radius 16, a 3px edge, and
   an optional message below the label. */

.gs-feedback {
  display: inline-grid;
  /* How long a correct or wrong plate holds before it fades: the drawing's
     1200ms. No motion token is a hold, so it is six emphasis beats, which
     also keeps it under reduced motion, where every movement token is zeroed
     and emphasis is not. Token request: motion.hold. */
  --gs-feedback-hold: calc(var(--gs-motion-emphasis) * 6);
}

/* The element that moves. Which way it moves is data-gs-motion's, applied by
   packages/tokens/motion.css from the drawing's own keyframes: pop, shake,
   floatup or slam, one per outcome. Nothing here is timed and no keyframe is
   defined here for them.

   Each is an `animation`, not a `transition`: the element mounts once, on
   settlement, with nothing earlier on screen to transition from. Under
   reduced motion, tokens.css forces animation-duration to 0s on anything
   carrying data-gs-animates="motion", so the keyframe still runs, just
   instantly, and its default fill-mode (none) leaves the plate sitting at its
   ordinary, fully visible style rather than frozen on a faded-out frame. */
.gs-feedback__motion {
  display: inline-flex;
  align-items: center;
  gap: var(--gs-space-gap);
  /* A button when the reward waits to be tapped; the plate is the plate. */
  margin: 0;
  font: inherit;
  cursor: inherit;
}

button.gs-feedback__motion {
  cursor: pointer;
}

/* -- the plates ------------------------------------------------------------ */
/* Correct, wrong and reward are a word on a plate: the control radius, the
   ui stroke, the title face in capitals where the theme's primary action
   shouts. Correct is filled with positive, ringed in the edge, standing on a
   shelf and tilted; wrong is the surface with a dashed negative ring and no
   shelf, which is the frame reduced motion keeps when the shake goes; reward
   is the surface on the reward ring with the shelf. */
.gs-feedback[data-gs-feedback='correct'] .gs-feedback__motion,
.gs-feedback[data-gs-feedback='wrong'] .gs-feedback__motion,
.gs-feedback[data-gs-feedback='reward'] .gs-feedback__motion {
  box-sizing: border-box;
  /* The drawing pads 12 18; there is no 18px space token, so space.4 and the
     pair carries the 2px. Token request in the round 5 report. */
  padding: var(--gs-space-3) var(--gs-space-4);
  border: var(--gs-stroke-ui) solid var(--gs-color-edge);
  border-radius: var(--gs-radius-control);
  text-align: left;
}

.gs-feedback[data-gs-feedback='correct'] .gs-feedback__motion {
  color: var(--gs-color-on-bright);
  background: var(--gs-color-positive);
  box-shadow: 0 var(--gs-press-travel) 0 var(--gs-color-edge);
  /* The drawing's three-degree tilt, a resting transform rather than motion.
     The pop keyframe overrides it while it plays and hands it back after. */
  transform: rotate(-3deg);
}

.gs-feedback[data-gs-feedback='wrong'] .gs-feedback__motion {
  color: var(--gs-color-negative-solid);
  background: var(--gs-color-surface);
  border-style: dashed;
  border-color: var(--gs-color-negative-solid);
}

/* The reward ring is the drawing's `0 0 0 3px reward` with a soft glow and
   the 6px shelf. The ring and the shelf are here; the glow, 0 0 22px of the
   reward colour at half alpha, is a soft glow no depth token carries, and the
   pair allows it with the token request. */
.gs-feedback[data-gs-feedback='reward'] .gs-feedback__motion {
  color: var(--gs-color-ink);
  background: var(--gs-color-surface);
  box-shadow:
    0 0 0 var(--gs-stroke-ui) var(--gs-color-reward-solid),
    0 var(--gs-press-travel) 0 var(--gs-color-edge);
}

/* -- the words ------------------------------------------------------------- */
.gs-feedback__text {
  display: inline-flex;
  flex-direction: column;
  align-items: flex-start;
}

/* The word on the plate: the drawing sets it at 900 18px in the display face.
   Arcade's title is that face at 900 20px, the nearest token, and the pair
   carries the 2px. Token request in the round 5 report. */
.gs-feedback__label {
  font-family: var(--gs-type-title-font-family);
  font-size: var(--gs-type-title-font-size);
  font-weight: var(--gs-type-title-font-weight);
  line-height: 1;
  /* One property borrowed from the action axis, not the axis re-implemented:
     the result word shouts where the theme's primary action shouts. */
  text-transform: var(--gs-type-action-text-transform-primary, var(--gs-type-action-text-transform, none));
  /* Emphasis, not motion: the colour change survives reduced motion, because
     that is how a player who cannot see movement still gets the answer. */
  transition: color var(--gs-motion-emphasis) ease-out;
}

/* A reward's name is smaller than a result word, 900 15px drawn, under its
   kicker: figure is the display face at 900 14px. */
.gs-feedback[data-gs-feedback='reward'] .gs-feedback__label {
  font-family: var(--gs-type-figure-font-family);
  font-size: var(--gs-type-figure-font-size);
  font-weight: var(--gs-type-figure-font-weight);
}

/* The kicker over a reward's name, EARNED: the eyebrow role, in capitals, in
   the secondary ink. The drawing sets it at 9px; 12px is the floor for a
   label on a phone. */
.gs-feedback__note {
  font-family: var(--gs-type-eyebrow-font-family);
  font-size: var(--gs-type-eyebrow-font-size);
  font-weight: var(--gs-type-eyebrow-font-weight);
  letter-spacing: var(--gs-type-eyebrow-letter-spacing);
  text-transform: var(--gs-type-eyebrow-text-transform, uppercase);
  line-height: 1.2;
  color: var(--gs-color-ink-secondary);
}

/* The optional line under the word: the reason, in the body role, in the
   plate's own ink. The drawing names it at 13px; body is 17px by Tom's floor. */
.gs-feedback__detail {
  font-family: var(--gs-type-body-font-family);
  font-size: var(--gs-type-body-font-size);
  font-weight: var(--gs-type-body-font-weight);
  line-height: var(--gs-type-body-line-height);
  margin-top: var(--gs-space-1);
}

/* -- the mark -------------------------------------------------------------- */
/* A disc holding the glyph, because colour alone is not an answer. On the
   correct plate the disc is the dark ink and the tick is light; on the wrong
   plate the disc is negative, ringed in the edge, and the cross is light; on
   the reward card the disc is the reward colour, ringed in the edge, with the
   star. The drawing draws the discs at 28 and the reward's at 36; icon.control
   is 24 and control.small 40, and the pairs carry the token requests. */
.gs-feedback__glyph {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex: none;
  box-sizing: border-box;
  inline-size: var(--gs-size-icon-control);
  block-size: var(--gs-size-icon-control);
  border-radius: var(--gs-radius-full);
  font-size: var(--gs-size-icon-utility);
  line-height: 1;
  color: var(--gs-color-ink);
  transition: opacity var(--gs-motion-emphasis) ease-out;
}

.gs-feedback[data-gs-feedback='correct'] .gs-feedback__glyph {
  background: var(--gs-color-on-bright);
}

.gs-feedback[data-gs-feedback='wrong'] .gs-feedback__glyph {
  background: var(--gs-color-negative);
  border: var(--gs-stroke-ui) solid var(--gs-color-edge);
}

.gs-feedback[data-gs-feedback='reward'] .gs-feedback__glyph {
  inline-size: var(--gs-size-control-small);
  block-size: var(--gs-size-control-small);
  background: var(--gs-color-reward);
  border: var(--gs-stroke-ui) solid var(--gs-color-edge);
  color: var(--gs-color-on-bright);
}

/* -- the points ------------------------------------------------------------ */
/* No plate: the number itself, in positive, standing on the display shadow,
   is the signal. The drawing sets it at 900 28px (its `type.stat.lg`); stat
   is 22 and score 34, so it is the stat size and the pair carries the token
   request. */
.gs-feedback[data-gs-feedback='score'] .gs-feedback__label {
  font-size: var(--gs-type-stat-font-size);
  color: var(--gs-color-positive-solid);
}

/* -- the lifetime ---------------------------------------------------------- */
/* Only when the host asked to be told (`onDismiss`): correct and wrong hold,
   then fade over the emphasis beat; a score fades once its float has ended,
   and stays where the float left it in between; a reward fades when tapped.
   The fade is on the root, which is not a motion element, so reduced motion
   leaves it its 200ms rather than zeroing it, and the plate is still read
   before it goes. */
@keyframes gs-feedback-exit {
  to { opacity: 0; }
}

.gs-feedback--timed {
  animation: gs-feedback-exit var(--gs-motion-emphasis) ease-out var(--gs-feedback-hold) forwards;
}

/* The float ends at opacity 0 and must stay there, timed or not. It had the
   default fill-mode, so at 600ms the "+50" reverted to the base rule,
   reappeared where it started and stayed on screen until the host removed it
   (GSUI-85). Scoping this to `--timed` put that defect back for every host
   that does not pass onDismiss, which is what the gallery does. */
.gs-feedback[data-gs-feedback='score'] .gs-feedback__motion {
  animation-fill-mode: forwards;
}

.gs-feedback--exit {
  animation: gs-feedback-exit var(--gs-motion-emphasis) ease-out forwards;
}

/* -- reduced motion -------------------------------------------------------- */
/* No transform: the tilt goes with the movement, and a zero-length float must
   not leave the number on its invisible last frame. Fill, glyph and text
   still change, and the hold and the fade above still run. */
@media (prefers-reduced-motion: reduce) {
  .gs-feedback[data-gs-feedback='correct'] .gs-feedback__motion {
    transform: none;
  }

  /* A different path, not a shorter one. `forwards` on a zeroed duration would
     land on the last frame at once and the "+50" would never be readable, so
     under reduced motion the float does not run and the number simply stays. */
  .gs-feedback[data-gs-feedback='score'] .gs-feedback__motion {
    animation: none;
  }
}
